    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult result)
        {
            result.Log("PROJECT " + Application.dataPath);
            foreach (var i in Enumerable.Range(0, SceneManager.sceneCount))
            {
                var s = SceneManager.GetSceneAt(i);
                result.Log("SCENE " + s.path + " dirty=" + s.isDirty);
            }

            result.Log("repair class available; active bindings=" + Object.FindObjectsByType<CampusSim.CampusTerrainBinding>(FindObjectsSortMode.None).Length);
        }
    }
}
